with tempfile.TemporaryDirectory() as temp:
 root=Path(temp)
 for name,content in sources.items():
  path=root/'src'/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content)
 out=root/'classes';out.mkdir()
 subprocess.run(['javac','-encoding','UTF-8','-d',str(out),*map(str,(root/'src').rglob('*.java')),'src/HudEditor.java'],check=True)
 subprocess.run(['java','-cp',str(out),'luma.ui.HudEditorFacadeTest'],check=True)
